import {sha256} from './core.js';
export const FIRMWARE_LIMIT=32*1024*1024;
const signatures=[['CPIO newc',[48,55,48,55,48,49]],['CPIO crc',[48,55,48,55,48,50]],['bzip2',[66,90,104]],['xz',[253,55,122,88,90,0]],['ELF',[127,69,76,70]],['gzip',[31,139,8]],['ZIP',[80,75,3,4]],['SquashFS (little endian)',[104,115,113,115]],['SquashFS (big endian)',[115,113,115,104]],['UBI',[85,66,73,35]],['uImage',[39,5,25,86]],['TAR marker',[117,115,116,97,114]]];
export function reviewText(text){const flags=[];if(/(?:password|passwd|secret|api[_-]?key|access[_-]?token|private[_-]?key)\s*[=:]\s*\S+/i.test(text)||/-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/.test(text))flags.push({kind:'Sensitive value candidate',sensitive:true});if(/(?:debug\s*[=:]\s*(?:1|true|yes)|PermitRootLogin\s+yes|telnetd\b|allow_anonymous\s+(?:true|yes))/i.test(text))flags.push({kind:'Debug / access configuration candidate',sensitive:false});if(/(?:busybox|openssl|dropbear|linux version|u-boot)[ /:_-]*v?\d+\.\d+/i.test(text))flags.push({kind:'Component / version clue',sensitive:false});return flags;}
export function redactText(text){return text.replace(/-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----[\s\S]*?(?:-----END (?:RSA |EC |OPENSSH )?PRIVATE KEY-----|$)/g,'[Private key block masked]').split('\n').map(line=>maskedText(line)).join('\n');}
export const maskedText=(text,reveal=false)=>!reveal&&reviewText(text).some(f=>f.sensitive)?'[Sensitive candidate masked — inspect original deliberately]':text;
function entropy(counts,size){if(!size)return 0;let result=0;for(const n of counts)if(n){const p=n/size;result-=p*Math.log2(p)}return Number(result.toFixed(4));}
export async function inspectFirmware(bytes,progress=()=>{}){
  if(!(bytes instanceof Uint8Array)||bytes.length>FIRMWARE_LIMIT)throw Error('Use a firmware image of 32 MiB or less.');
  const counts=new Uint32Array(256),bins=[],strings=[],headers=[],review=[];let local=new Uint32Array(256),run='',runStart=0,runLength=0,stringLimit=false,privateBlock=false;
  const flush=()=>{if(runLength>=6){if(strings.length<5000){if(/-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/.test(run))privateBlock=true;const rec={offset:runStart,text:run,truncated:runLength>512,sensitive:privateBlock};strings.push(rec);const flags=reviewText(run);if(privateBlock&&!flags.some(f=>f.sensitive))flags.push({kind:'Private key block candidate',sensitive:true});for(const f of flags)review.push({...f,offset:runStart});if(/-----END (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/.test(run))privateBlock=false;}else stringLimit=true;}run='';runLength=0;};
  const byFirst=new Map();for(const item of signatures){const first=item[1][0];if(!byFirst.has(first))byFirst.set(first,[]);byFirst.get(first).push(item);}
  for(let i=0;i<bytes.length;i++){
    const b=bytes[i];counts[b]++;local[b]++;
    if(b>=32&&b<=126){if(!runLength)runStart=i;runLength++;if(run.length<512)run+=String.fromCharCode(b);}else flush();
    if(headers.length<1024)for(const [kind,magic] of byFirst.get(b)||[]){if(magic.every((x,j)=>bytes[i+j]===x)){const offset=kind==='TAR marker'?i-257:i;if(offset>=0)headers.push({offset,kind,confidence:'Candidate signature; structure not validated'});}}
    if((i+1)%65536===0||i===bytes.length-1){const size=(i%65536)+1;bins.push({offset:Math.floor(i/65536)*65536,size,entropy:entropy(local,size)});local=new Uint32Array(256);}
    if((i+1)%1048576===0)progress({phase:'Inspecting bytes',done:i+1,total:bytes.length});
  }flush();
  let architecture='Unidentified';if(bytes[0]===127&&bytes[1]===69&&bytes[2]===76&&bytes[3]===70&&bytes.length>=20){const n=bytes[5]===1?bytes[18]+bytes[19]*256:bytes[18]*256+bytes[19];architecture=({3:'x86',8:'MIPS',40:'ARM',62:'x86-64',183:'AArch64',243:'RISC-V'})[n]||'ELF machine '+n;architecture+=' (ELF header clue)';}
  progress({phase:'Hashing original',done:bytes.length,total:bytes.length});
  return {analysisVersion:2,size:bytes.length,hash:await sha256(bytes),entropy:entropy(counts,bytes.length),kind:headers.find(h=>h.offset===0)?.kind||'Unrecognized / raw binary',architecture,bins,stringRecords:strings,strings:strings.map(s=>s.text),stringLimit,headers,headerLimit:headers.length>=1024,review};
}
export function searchBytes(bytes,query,mode='text',max=500){let pattern;if(mode==='hex'){const clean=query.replace(/\s+/g,'');if(!/^(?:[a-f0-9]{2})+$/i.test(clean)||clean.length>512)throw Error('Enter 1–256 complete hex byte pairs.');pattern=Uint8Array.from(clean.match(/../g),s=>parseInt(s,16));}else{pattern=new TextEncoder().encode(query);if(!pattern.length||pattern.length>256)throw Error('Enter 1–256 UTF-8 bytes.');}const failure=new Uint16Array(pattern.length);for(let i=1,j=0;i<pattern.length;i++){while(j&&pattern[i]!==pattern[j])j=failure[j-1];if(pattern[i]===pattern[j])j++;failure[i]=j;}const matches=[];for(let i=0,j=0;i<bytes.length;i++){while(j&&bytes[i]!==pattern[j])j=failure[j-1];if(bytes[i]===pattern[j])j++;if(j===pattern.length){if(matches.length===max)return {matches,limited:true};matches.push(i-pattern.length+1);j=failure[j-1];}}return {matches,limited:false};}
export function compareFirmware(a,b){let changedBytes=0,start=-1,ranges=[],rangeCount=0;const finish=end=>{if(start>=0){rangeCount++;if(ranges.length<200)ranges.push({start,end,length:end-start});start=-1;}};for(let i=0;i<Math.max(a.length,b.length);i++){if(a[i]!==b[i]){changedBytes++;if(start<0)start=i;}else finish(i);}finish(Math.max(a.length,b.length));return {beforeSize:a.length,afterSize:b.length,changedBytes,ranges,rangeCount,rangesLimited:rangeCount>ranges.length};}
export function compareInventories(a=[],b=[]){const old=new Map(a.map(f=>[f.path,f])),current=new Map(b.map(f=>[f.path,f])),changes=[];const metadata=f=>JSON.stringify(Object.entries(f.metadata||{}).sort(([a],[b])=>a.localeCompare(b)));for(const [name,f] of current){const was=old.get(name);if(!was)changes.push({path:name,change:'Added',afterHash:f.sha256});else if(was.sha256!==f.sha256||metadata(was)!==metadata(f))changes.push({path:name,change:was.sha256!==f.sha256?'Changed':'Metadata changed',beforeHash:was.sha256,afterHash:f.sha256,beforeMetadata:was.metadata||{},afterMetadata:f.metadata||{}});}for(const [name,f] of old)if(!current.has(name))changes.push({path:name,change:'Removed',beforeHash:f.sha256});return changes;}
export function hexPage(bytes,start=0,length=256){const rows=[];start=Math.max(0,Math.floor(start/16)*16);for(let i=start;i<Math.min(bytes.length,start+length);i+=16){const slice=bytes.subarray(i,i+16);rows.push(i.toString(16).padStart(8,'0')+'  '+Array.from(slice,b=>b.toString(16).padStart(2,'0')).join(' ').padEnd(47)+'  '+Array.from(slice,b=>b>=32&&b<=126?String.fromCharCode(b):'.').join(''));}return rows.join('\n')||'(empty region)';}
export async function validateExtraction(e){if(e?.format!=='probe-extraction-v1'||!Array.isArray(e.files)||e.files.length>500||!Array.isArray(e.errors)||! /^[a-f0-9]{64}$/.test(e.sourceHash||''))throw Error('Invalid extraction manifest.');let total=0;const paths=new Set();for(const f of e.files){if(typeof f.path!=='string'||!f.path||f.path.length>512||(/[\x00-\x1f:]/.test(f.path))||f.path.startsWith('/')||f.path.includes('\\')||f.path.split('/').some(p=>p==='..'||p==='.'||p==='')||paths.has(f.path)||!Number.isInteger(f.size)||f.size<0||f.size>4*1024*1024)throw Error('Unsafe extraction entry.');paths.add(f.path);if(f.metadata!==undefined&&(!f.metadata||typeof f.metadata!=='object'||Array.isArray(f.metadata)||Object.entries(f.metadata).some(([k,v])=>!['mode','uid','gid','mtime'].includes(k)||!Number.isSafeInteger(v)||v<0||v>(k==='mode'?4095:0xffffffff))))throw Error('Invalid extraction metadata.');if(typeof f.dataBase64!=='string'||f.dataBase64.length>Math.ceil(f.size/3)*4+4||/[^A-Za-z0-9+/=]/.test(f.dataBase64))throw Error('Invalid extraction payload.');const bytes=Uint8Array.from(atob(f.dataBase64),c=>c.charCodeAt(0));total+=bytes.length;if(bytes.length!==f.size||total>16*1024*1024||await sha256(bytes)!==f.sha256)throw Error('Extracted file integrity check failed.');}return e;}
